  "private session items": "\u0639\u0646\u0627\u0635\u0631 \u062C\u0644\u0633\u0629 \u062E\u0627\u0635\u0629",
  "upstream items loaded": "\u0639\u0646\u0627\u0635\u0631 \u0645\u0635\u062F\u0631\u064A\u0629 \u062A\u0645 \u062A\u062D\u0645\u064A\u0644\u0647\u0627",
  "/about": "/\u062D\u0648\u0644",
  "AI & media": "\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0637",
  "AI image prompt": "\u0648\u0635\u0641 \u0635\u0648\u0631\u0629 \u0644\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A",
  "Accent color": "\u0644\u0648\u0646 \u0627\u0644\u062A\u0645\u064A\u064A\u0632",
  "Accordion": "\u0623\u0643\u0648\u0631\u062F\u064A\u0648\u0646",
  "Add a call-to-action button.": "\u0623\u0636\u0641 \u0632\u0631 \u062F\u0639\u0648\u0629 \u0644\u0644\u0625\u062C\u0631\u0627\u0621.",
  "Add a contact section and form.": "\u0623\u0636\u0641 \u0642\u0633\u0645 \u0627\u062A\u0635\u0627\u0644 \u0648\u0646\u0645\u0648\u0630\u062C\u064B\u0627.",
  "Add a countdown timer.": "\u0623\u0636\u0641 \u0639\u062F\u0627\u062F\u064B\u0627 \u062A\u0646\u0627\u0632\u0644\u064A\u064B\u0627.",
  "Add a features section.": "\u0623\u0636\u0641 \u0642\u0633\u0645 \u0627\u0644\u0645\u064A\u0632\u0627\u062A.",
  "Add a flexible section you can fully restyle and replace with your own elements.": "\u0623\u0636\u0641 \u0642\u0633\u0645\u064B\u0627 \u0645\u0631\u0646\u064B\u0627 \u064A\u0645\u0643\u0646\u0643 \u0625\u0639\u0627\u062F\u0629 \u062A\u0646\u0633\u064A\u0642\u0647 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0627\u0633\u062A\u0628\u062F\u0627\u0644\u0647 \u0628\u0639\u0646\u0627\u0635\u0631\u0643.",
  "Add a footer section.": "\u0623\u0636\u0641 \u0642\u0633\u0645 \u062A\u0630\u064A\u064A\u0644.",
  "Add a hero section.": "\u0623\u0636\u0641 \u0642\u0633\u0645 \u0628\u0637\u0644.",
  "Add a pricing section.": "\u0623\u0636\u0641 \u0642\u0633\u0645 \u0623\u0633\u0639\u0627\u0631.",
  "Add a services section.": "\u0623\u0636\u0641 \u0642\u0633\u0645 \u062E\u062F\u0645\u0627\u062A.",
  "Add a structured list of items.": "\u0623\u0636\u0641 \u0642\u0627\u0626\u0645\u0629 \u0645\u0646\u0638\u0645\u0629 \u0645\u0646 \u0627\u0644\u0639\u0646\u0627\u0635\u0631.",
  "Add a testimonials section.": "\u0623\u0636\u0641 \u0642\u0633\u0645 \u0634\u0647\u0627\u062F\u0627\u062A \u0627\u0644\u0639\u0645\u0644\u0627\u0621.",
  "Add a title or section heading.": "\u0623\u0636\u0641 \u0639\u0646\u0648\u0627\u0646\u064B\u0627 \u0623\u0648 \u062A\u0631\u0648\u064A\u0633\u0629 \u0642\u0633\u0645.",
  "Add an about section.": "\u0623\u0636\u0641 \u0642\u0633\u0645 \u0646\u0628\u0630\u0629.",
  "Add an image from uploads or AI.": "\u0623\u0636\u0641 \u0635\u0648\u0631\u0629 \u0645\u0646 \u0627\u0644\u0631\u0641\u0639 \u0623\u0648 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A.",
  "Add controlled visual spacing.": "\u0623\u0636\u0641 \u0645\u0633\u0627\u0641\u0629 \u0628\u0635\u0631\u064A\u0629 \u0645\u0636\u0628\u0648\u0637\u0629.",
  "Add paragraph or supporting copy.": "\u0623\u0636\u0641 \u0641\u0642\u0631\u0629 \u0623\u0648 \u0646\u0635\u064B\u0627 \u062F\u0627\u0639\u0645\u064B\u0627.",
  "Add sanitized custom HTML.": "\u0623\u0636\u0641 HTML \u0645\u062E\u0635\u0635\u064B\u0627 \u0648\u0645\u0639\u0642\u0645\u064B\u0627.",
